import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { parse } from 'yaml';

// Synthetic extension companies (generated by scripts/generate_synthetic.py); the original dataset is never touched.
const SYN_ROOT = path.resolve('synthetic/extension-v1');

export interface CompanySummary {
  companyId: string;
  name: string;
  industry: string;
  profile: string;
  billCount: number;
  scenario?: boolean;
  synthetic?: boolean;
  derivedFrom?: string;
}

export interface Evidence { id: string; kind: string; date: string; title: string; text: string }
export interface RelatedBill { id: string; docNumber: string; vendor: string; date: string; amountCents: number; description: string; memo: string }

export interface Row {
  id: string; // company-scoped: "<companyId>:<billId>"
  companyId: string;
  billId: string;
  docNumber: string;
  date: string;
  dueDate: string;
  vendor: string;
  vendorId: string;
  description: string;
  itemNames: string[];
  account: string;
  amountCents: number;
  expenseKind: string;
  costCategory: string;
  memo: string;
  project: string | null;
  supplyRole: string | null;
  lines: Record<string, unknown>[];
  payments: { id: string; date: string; amountCents: number; account: string }[];
  vendorRecord: Record<string, unknown> | null;
  projectRecord: Record<string, unknown> | null;
  /** Synthetic extension only: supporting business records linked to this bill, and nearby bills from the same vendor. */
  evidence?: Evidence[];
  related?: RelatedBill[];
  /** Synthetic extension only: which kind of transaction this row is, plus type-specific fields. */
  txnType?: 'bill' | 'invoice' | 'bank';
  details?: Record<string, string>;
}

export interface CompanyBills {
  company: CompanySummary;
  totalBills: number;
  sampled: boolean;
  rows: Row[];
  disclosure?: string;
  /** Hash of a generated dataset's files; the workspace re-seeds the company when it changes. */
  datasetVersion?: string;
}

let synIndex: Record<string, any>[] | null = null;
let synMtime = -1;
const cache = new Map<string, CompanyBills>();
const rowById = new Map<string, Row>();
function refreshSynthetic() {
  const file = path.join(SYN_ROOT, 'index.json');
  const mtime = fs.existsSync(file) ? fs.statSync(file).mtimeMs : 0;
  if (mtime === synMtime) return;
  synMtime = mtime;
  synIndex = null;
  for (const [id, value] of [...cache]) {
    if (value.datasetVersion) {
      cache.delete(id);
      for (const row of value.rows) rowById.delete(row.id);
    }
  }
}
function readSynthetic() {
  refreshSynthetic();
  const file = path.join(SYN_ROOT, 'index.json');
  synIndex ??= fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : [];
  return synIndex!;
}
const isSynthetic = (companyId: string) => readSynthetic().some(r => r.company_id === companyId);

/** Bill ids in the curated demo sample for a synthetic company (a disclosed, enriched selection). */
export function demoSample(companyId: string): { ids: Set<string>; disclosure: string } | null {
  const file = path.join(SYN_ROOT, 'demo_sample.json');
  if (!isSynthetic(companyId) || !fs.existsSync(file)) return null;
  const sample = JSON.parse(fs.readFileSync(file, 'utf8'));
  return sample.samples?.[companyId] ? { ids: new Set<string>(sample.samples[companyId]), disclosure: sample.disclosure } : null;
}
function datasetVersion(dir: string): string {
  const hash = crypto.createHash('sha1');
  for (const file of fs.readdirSync(dir).filter((f) => f.endsWith('.yaml')).sort()) hash.update(file).update(fs.readFileSync(path.join(dir, file)));
  return hash.digest('hex');
}
function syntheticDisclosure(): string {
  const file = path.join(SYN_ROOT, 'DISCLOSURE.json');
  return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')).disclosure : 'Synthetic extension company.';
}
/** Only the four app-facing synthetic companies are available to HTTP callers. */
export function listCompanies(): CompanySummary[] {
  return readSynthetic().filter(r => /^company-10[1-4]$/.test(r.company_id)).map(r => ({
    companyId: r.company_id, name: r.display_name, industry: r.industry_title,
    profile: r.profile, billCount: r.entity_counts.transactions ?? r.entity_counts.bills,
    synthetic: true, derivedFrom: r.derived_from,
  }));
}

function worldDir(companyId: string) {
  if (!listCompanies().some(company => company.companyId === companyId)) throw new Error('unknown company');
  const base = path.join(SYN_ROOT, companyId, 'rwm-v4');
  const world = fs.readdirSync(base).find((d) => d.startsWith('world-'));
  if (!world) throw new Error('world dir not found');
  return path.join(base, world);
}

export function companyAccounts(companyId: string): { id: string; name: string }[] {
  return loadYaml(worldDir(companyId), 'accounts').filter(account => account.active !== false && account.is_active !== false)
    .map(account => ({ id: String(account.id), name: String(account.name) }));
}

function loadYaml(dir: string, entity: string): any[] {
  const file = path.join(dir, `${entity}.yaml`);
  if (!fs.existsSync(file)) return [];
  return parse(fs.readFileSync(file, 'utf8')) ?? [];
}

/** "1234.56" -> 123456, parsed from the string so no float is involved. */
export function toCents(amount: string | null | undefined): number {
  if (!amount) return 0;
  const m = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(String(amount));
  if (!m) throw new Error(`bad money string: ${amount}`);
  const cents = Number(m[2]) * 100 + Number((m[3] ?? '').padEnd(2, '0') || 0);
  return m[1] ? -cents : cents;
}

export { formatCents } from '../src/jevEvidence.ts';

// Drop simulation-only metadata (sim_*, provenance_note) from anything shown or sent to Jev.
function strip<T>(obj: T): T {
  if (Array.isArray(obj)) return obj.map(strip) as T;
  if (obj && typeof obj === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(obj)) {
      if (k.startsWith('sim_') || k === 'provenance_note' || v === undefined) continue;
      out[k] = strip(v);
    }
    return out as T;
  }
  return obj;
}

export function getRow(id: string): Row | undefined {
  return rowById.get(id);
}

export function loadCompanyBills(companyId: string): CompanyBills {
  refreshSynthetic();
  const hit = cache.get(companyId);
  if (hit) return hit;
  const summary = listCompanies().find((c) => c.companyId === companyId);
  if (!summary) throw new Error('unknown company');
  const dir = worldDir(companyId);
  const bills = loadYaml(dir, 'bills');
  const vendors = new Map(loadYaml(dir, 'vendors').map((v) => [v.id, v]));
  const accounts = new Map(loadYaml(dir, 'accounts').map((a) => [a.id, a]));
  const projects = new Map(loadYaml(dir, 'projects').map((p) => [p.id, p]));
  const items = new Map(loadYaml(dir, 'items').map((i) => [i.id, i]));
  const payByBill = new Map<string, Row['payments']>();
  for (const p of loadYaml(dir, 'bill_payments')) {
    for (const app of p.applications ?? []) {
      const list = payByBill.get(app.document_id) ?? [];
      list.push({
        id: p.id,
        date: p.txn_date,
        amountCents: toCents(app.amount),
        account: accounts.get(p.payment_account_id)?.name ?? p.payment_account_id,
      });
      payByBill.set(app.document_id, list);
    }
  }

  bills.sort((a, b) => (a.txn_date < b.txn_date ? -1 : a.txn_date > b.txn_date ? 1 : a.id < b.id ? -1 : 1));
  const sampled = false;

  const rows: Row[] = bills.map((b) => {
    const vendor = vendors.get(b.vendor_id);
    const project = b.project_id ? projects.get(b.project_id) : null;
    const itemLines = b.item_lines ?? [];
    const acctLines = b.account_lines ?? [];
    // description = the bill lines' own description text, verbatim; item names are kept separate.
    const lineText = [...itemLines, ...acctLines].map((l: any) => l.description).filter(Boolean);
    const description = [...new Set<string>(lineText)].join(' | ');
    const itemNames: string[] = itemLines.map((l: any) => l.item_name).filter(Boolean);
    let account = '';
    if (itemLines.length) {
      account = accounts.get(items.get(itemLines[0].item_id)?.purchase_account_id)?.name ?? 'Inventory purchases';
    } else if (acctLines.length) {
      account = acctLines[0].account_name ?? accounts.get(acctLines[0].account_id)?.name ?? '';
    }
    return {
      id: `${companyId}:${b.id}`,
      companyId,
      billId: b.id,
      docNumber: b.doc_number,
      date: b.txn_date,
      dueDate: b.due_date,
      vendor: b.vendor_name,
      vendorId: b.vendor_id,
      description,
      itemNames,
      account,
      amountCents: toCents(b.total_amount),
      expenseKind: b.expense_kind,
      costCategory: b.cost_category,
      memo: b.memo ?? '',
      project: project?.name ?? null,
      supplyRole: vendor?.supply_role ?? null,
      lines: strip([...itemLines, ...acctLines]),
      payments: payByBill.get(b.id) ?? [],
      vendorRecord: vendor ? strip(vendor) : null,
      projectRecord: project ? strip({ ...project, status_history: undefined, change_orders: undefined, reschedules: undefined }) : null,
    };
  });

  if (summary.synthetic) {
    // Synthetic extensions also carry customer invoices and bank transactions as reviewable rows.
    const customers = new Map(loadYaml(dir, 'customers').map((c) => [c.id, c]));
    const company = loadYaml(dir, 'company')[0] ?? {};
    const receipts = new Map<string, Row['payments']>();
    for (const p of loadYaml(dir, 'customer_payments')) {
      for (const app of p.applications ?? []) receipts.set(app.document_id, [...(receipts.get(app.document_id) ?? []), { id: p.id, date: p.txn_date, amountCents: toCents(app.amount), account: accounts.get(p.deposit_account_id)?.name ?? p.deposit_account_id }]);
    }
    for (const row of rows) row.txnType = 'bill';
    for (const inv of loadYaml(dir, 'invoices')) {
      const project = inv.project_id ? projects.get(inv.project_id) : null;
      rows.push({
        id: `${companyId}:${inv.id}`, companyId, billId: inv.id, docNumber: inv.doc_number, date: inv.txn_date, dueDate: inv.due_date,
        vendor: inv.customer_name, vendorId: inv.customer_id, description: inv.lines.map((l: any) => l.description).filter(Boolean).join(' | '),
        itemNames: inv.lines.map((l: any) => l.item_name).filter(Boolean), account: accounts.get(inv.income_account_id)?.name ?? 'Income', amountCents: toCents(inv.total_amount),
        expenseKind: 'revenue', costCategory: 'sales', memo: inv.memo ?? '', project: project?.name ?? null, supplyRole: 'customer', lines: strip(inv.lines),
        payments: receipts.get(inv.id) ?? [], vendorRecord: customers.has(inv.customer_id) ? strip(customers.get(inv.customer_id)) : null,
        projectRecord: project ? strip({ ...project, status_history: undefined, change_orders: undefined, reschedules: undefined }) : null, txnType: 'invoice',
        details: { remit_to_account_ending: String(inv.remit_to_account_ending), company_remit_account_ending: String(company.remit_account_ending ?? ''), deposit_applied: inv.deposit_applied_amount, retainage_held: inv.retainage_amount },
      });
    }
    for (const t of loadYaml(dir, 'bank_transactions')) {
      const party = t.counterparty_id ? (vendors.get(t.counterparty_id) ?? customers.get(t.counterparty_id)) : null;
      rows.push({
        id: `${companyId}:${t.id}`, companyId, billId: t.id, docNumber: t.reference, date: t.date, dueDate: t.date, vendor: t.counterparty ?? '', vendorId: t.counterparty_id ?? '',
        description: t.description ?? '', itemNames: [], account: accounts.get(t.account_id)?.name ?? 'Business Checking', amountCents: toCents(t.amount), expenseKind: 'bank',
        costCategory: t.direction, memo: t.memo ?? '', project: null, supplyRole: null, lines: [], payments: [], vendorRecord: party ? strip(party) : null, projectRecord: null,
        txnType: 'bank', details: { direction: t.direction, channel: t.channel, counterparty_account_ending: String(t.counterparty_account_ending ?? ''), reference: t.reference },
      });
    }
    rows.sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id));
    const evidenceByTx = new Map<string, Evidence[]>();
    for (const e of loadYaml(dir, 'evidence')) {
      for (const txId of e.transaction_ids ?? e.bill_ids ?? []) {
        const list = evidenceByTx.get(txId) ?? [];
        list.push({ id: e.id, kind: e.kind, date: e.date, title: e.title, text: e.text });
        evidenceByTx.set(txId, list);
      }
    }
    const day = (iso: string) => Date.parse(`${iso}T12:00:00Z`) / 86_400_000;
    const party = (r: Row) => r.vendorId || r.vendor;
    for (const row of rows) {
      row.evidence = (evidenceByTx.get(row.billId) ?? []).sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id));
      const window = row.txnType === 'bank' ? 30 : 60;
      row.related = rows
        .filter(o => o.txnType === row.txnType && party(o) === party(row) && o.billId !== row.billId && Math.abs(day(o.date) - day(row.date)) <= window)
        .sort((a, b) => Math.abs(day(a.date) - day(row.date)) - Math.abs(day(b.date) - day(row.date)) || a.billId.localeCompare(b.billId))
        .slice(0, 3)
        .map(o => ({ id: o.billId, docNumber: o.docNumber, vendor: o.vendor, date: o.date, amountCents: o.amountCents, description: o.description.slice(0, 90), memo: o.memo.slice(0, 90) }));
    }
  }
  const result: CompanyBills = { company: summary, totalBills: summary.synthetic ? rows.length : bills.length, sampled, rows, ...(summary.synthetic && { disclosure: syntheticDisclosure(), datasetVersion: datasetVersion(dir) }) };
  cache.set(companyId, result);
  for (const r of rows) rowById.set(r.id, r);
  return result;
}
